function clamp(v,a,b){v=Number(v);if(isNaN(v))v=0;if(v<a)return a;if(v>b)return b;return v;}
function esc(s){return String(s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];});}
function formatBytes(n){
  n=Number(n)||0; if(n<=0) return "0 B";
  var u=["B","KB","MB","GB"],i=0;
  while(n>=1024&&i<u.length-1){n/=1024;i++;}
  return (n>=100||i===0?Math.round(n):n.toFixed(1))+" "+u[i];
}
// 计算缩放后的尺寸：给宽推高、给高推宽（锁比例）；两者都给且锁比例则以宽为准
function computeResize(o){
  o=o||{};
  var w=Math.max(1,Math.round(o.w||1)), h=Math.max(1,Math.round(o.h||1));
  var lock=o.lockAspect!==false;
  var tw=o.targetW, th=o.targetH;
  var ar=w/h;
  if(tw&&!th){ tw=Math.round(tw); th=lock?Math.max(1,Math.round(tw/ar)):h; }
  else if(th&&!tw){ th=Math.round(th); tw=lock?Math.max(1,Math.round(th*ar)):w; }
  else if(tw&&th){ tw=Math.round(tw); th=lock?Math.max(1,Math.round(tw/ar)):Math.round(th); }
  else { tw=w; th=h; }
  return {w:Math.max(1,tw),h:Math.max(1,th)};
}
// 旋转后画布尺寸（90/270 交换宽高）
function rotateDims(w,h,deg){ deg=((deg%360)+360)%360; return (deg===90||deg===270)?{w:h,h:w}:{w:w,h:h}; }
// 把裁剪矩形约束到图像范围内并取整
function clampCrop(r,W,H){
  r=r||{};
  var x=clamp(r.x||0,0,W), y=clamp(r.y||0,0,H);
  var w=clamp(r.w||1,1,W-x), h=clamp(r.h||1,1,H-y);
  return {x:Math.round(x),y:Math.round(y),w:Math.max(1,Math.round(w)),h:Math.max(1,Math.round(h))};
}
// 构造 CSS filter 字符串（实时预览与导出共用，保证一致）
function buildFilterCSS(a){
  a=a||{}; var p=[];
  p.push("brightness("+(1+(Number(a.brightness)||0)/100).toFixed(3)+")");
  p.push("contrast("+(1+(Number(a.contrast)||0)/100).toFixed(3)+")");
  p.push("saturate("+(1+(Number(a.saturation)||0)/100).toFixed(3)+")");
  if(Number(a.hue)) p.push("hue-rotate("+Math.round(a.hue)+"deg)");
  if(Number(a.blur)>0) p.push("blur("+Number(a.blur)+"px)");
  if(a.sepiaOn) p.push("sepia(0.6)");
  if(a.grayscale) p.push("grayscale(1)");
  if(a.invert) p.push("invert(1)");
  return p.join(" ");
}
// 像素级调整（RGBA 平铺数组）—— 用于无 CSS filter 场景的兜底/测试；返回新数组
function adjustPixels(data,a){
  a=a||{};
  var out=data.slice?data.slice():Array.prototype.slice.call(data);
  var b=(Number(a.brightness)||0)*2.55;
  var c=(Number(a.contrast)||0)*2.55; var cf=(259*(c+255))/(255*(259-c));
  var sf=1+((Number(a.saturation)||0)/100);
  for(var i=0;i<out.length;i+=4){
    var r=out[i],g=out[i+1],bl=out[i+2];
    r+=b; g+=b; bl+=b;
    r=cf*(r-128)+128; g=cf*(g-128)+128; bl=cf*(bl-128)+128;
    var lum=0.299*r+0.587*g+0.114*bl;
    r=lum+(r-lum)*sf; g=lum+(g-lum)*sf; bl=lum+(bl-lum)*sf;
    if(a.grayscale){ var lg=0.299*r+0.587*g+0.114*bl; r=lg; g=lg; bl=lg; }
    if(a.invert){ r=255-r; g=255-g; bl=255-bl; }
    out[i]=clamp(Math.round(r),0,255); out[i+1]=clamp(Math.round(g),0,255); out[i+2]=clamp(Math.round(bl),0,255);
  }
  return out;
}
function extForMime(m){ return {"image/png":"png","image/jpeg":"jpg","image/webp":"webp"}[m]||"png"; }
function exportName(mime){ return "imageforge-"+Date.now()+"."+extForMime(mime); }

var __API={clamp:clamp,esc:esc,formatBytes:formatBytes,computeResize:computeResize,rotateDims:rotateDims,clampCrop:clampCrop,buildFilterCSS:buildFilterCSS,adjustPixels:adjustPixels,extForMime:extForMime,exportName:exportName};
if(typeof module!=='undefined'&&module.exports){ module.exports=__API; }
if(typeof window!=='undefined'){ window.ImageForgePure=__API; }
